187:                         const creatorMatch = xmlStr.match(/<dc:creator>([\s\S]*?)<\/dc:creator>/);
188:                         const pubMatch = xmlStr.match(/<dc:publisher>([\s\S]*?)<\/dc:publisher>/);
189:                         const dateMatch = xmlStr.match(/<dc:date>([\s\S]*?)<\/dc:date>/);
190:                         
191:                         const decodeHtml = (html) => {
192:                             const txt = document.createElement("textarea");
193:                             txt.innerHTML = html;
194:                             return txt.value;
195:                         };
196:                         
197:                         title = decodeHtml(titleMatch[1]);
198:                         author = creatorMatch ? decodeHtml(creatorMatch[1]) : "";
199:                         publisher = pubMatch ? decodeHtml(pubMatch[1]) : "";
200:                         year = dateMatch ? normalizeDate(dateMatch[1]) : "";
201:                     }
202:                 }
203:                 
204:                 // Google Books API Fallback
205:                 if (!title && !isMagazine) {
206:                     const gbRes = await fetch(`https://www.googleapis.com/books/v1/volumes?q=isbn:${decodedText}`);
207:                     if (gbRes.ok) {
208:                         const gbData = await gbRes.json();
209:                         if (gbData.items && gbData.items.length > 0) {
210:                             const info = gbData.items[0].volumeInfo;
211:                             title = info.title || "";
212:                             author = info.authors ? info.authors.join(", ") : "";
213:                             publisher = info.publisher || "";
214:                             year = normalizeDate(info.publishedDate || "");
215:                             officialDescription = info.description || "";
216:                         }
217:                     }
218:                 }
219: 
220:                 // GAS API Fallback (Rakuten Books Scrape)
221:                 if (!title) {
222:                     const gasUrl = document.getElementById('gasAppUrlInput') ? document.getElementById('gasAppUrlInput').value.trim() : "";
223:                     if (gasUrl) {
224:                         try {
225:                             const gasRes = await fetch(`${gasUrl}?action=search_isbn&isbn=${decodedText}`);
226:                             const gasData = await gasRes.json();
227:                             if (gasData && gasData.title) {
228:                                 title = gasData.title;
229:                                 author = gasData.author || "";
230:                                 publisher = gasData.publisher || "";
231:                             }
232:                         } catch (e) {
233:                             console.error("GAS fallback failed:", e);
234:                         }
235:                     }
236:                 }
237: 
238:                 // Title Sanitization (remove = English Title)
239:                 if (title) {
240:                     title = title.replace(/\s*=\s*[A-Za-z\s\.\-&:]+(?=\d+$)/, ' ').trim();
241:                     title = title.replace(/\s*=\s*[A-Za-z\s\.\-&:]+$/, '').trim();
242:                 }
243: 
244:                 if (title) {
245:                     showConfirmDetails(title, author, decodedText, publisher, year, officialDescription);
246:                 } else {
247:                     document.getElementById('confirmLoading').style.display = 'none';
248:                     document.getElementById('scanResult').innerText = "エラー: 本の情報が見つかりませんでした (コード: " + decodedText + ")";
249:                 }
250:             } catch (err) {
251:                 document.getElementById('confirmLoading').style.display = 'none';
252:                 document.getElementById('scanResult').innerText = "API通信エラー: " + err;
253:             }
254:         }
255:         
256:         fetchBookData();
257:     }
258: }
