339: function getAmazonCoverUrl(isbn13) {
340:     if (!isbn13) return '';
341:     let asin = isbn13;
342:     if (isbn13.startsWith('978') && isbn13.length === 13) {
343:         const base = isbn13.substring(3, 12);
344:         let sum = 0;
345:         for (let i = 0; i < 9; i++) {
346:             sum += parseInt(base[i]) * (10 - i);
347:         }
348:         const check = 11 - (sum % 11);
349:         const checkDigit = check === 10 ? 'X' : (check === 11 ? '0' : check.toString());
350:         asin = base + checkDigit;
351:     }
352:     return `https://images-na.ssl-images-amazon.com/images/P/${asin}.09.LZZZZZZZ.jpg`;
353: }
