368: function sendToGas(title, author, isbn, publisher, year, status, officialDescription = "") {
369:     // UIを隠して送信中メッセージを表示
370:     document.getElementById('confirmDetails').style.display = 'none';
371:     document.getElementById('scanResult').innerText = `【${title}】\nスプレッドシートへ送信中...`;
372:     
373:     // GAS Web Appに送信
374:     const gasUrl = localStorage.getItem('gasWebAppUrl');
375:     if(!gasUrl) {
376:         document.getElementById('scanResult').innerText = 'エラー: 設定画面から「GAS WebアプリのURL」を保存してください！';
377:         return;
378:     }
379:     
380:     // スマホブラウザのセキュリティ（ITPやCORSブロック）を完全に回避するため、
381:     // fetchではなく見えないフォーム（iframe）を使ってPOST送信する
382:     if (!document.getElementById('hidden_iframe')) {
383:         const iframe = document.createElement('iframe');
384:         iframe.name = 'hidden_iframe';
385:         iframe.id = 'hidden_iframe';
386:         iframe.style.display = 'none';
387:         document.body.appendChild(iframe);
388:     }
389:     
390:     const form = document.createElement('form');
391:     form.method = 'POST';
392:     form.action = gasUrl;
393:     form.target = 'hidden_iframe';
394:     
395:     const fields = { title, author, isbn, status, publisher, year, description: officialDescription };
396:     for (let key in fields) {
397:         if (fields[key]) {
398:             const input = document.createElement('input');
399:             input.type = 'hidden';
400:             input.name = key;
401:             input.value = fields[key];
402:             form.appendChild(input);
403:         }
404:     }
405:     
406:     document.body.appendChild(form);
407:     form.submit();
408:     document.body.removeChild(form);
409:     
410:     // 送信は一瞬で終わるので完了メッセージを表示
411:     document.getElementById('scanResult').innerText = `追加完了: ${title}\n\n※Geminiが要約を生成して追記しました。\n(画面を更新します)`;
412:     
413:     // Googleスプレッドシートの「ウェブに公開(CSV)」は、Google側のサーバー仕様で
414:     // 反映までに最大5分ほどのタイムラグが発生します。
415:     // その遅延をごまかすため、画面上（メモリ上）だけ先に本を追加して表示します。
416:     const newBook = {
417:         Title: title,
418:         Author: author,
419:         Status: status,
420:         Gemini_Summary: "（AIが要約を作成中です。数分後にリロードすると表示されます）",
421:         Tags: ""
422:     };
423:     
424:     setTimeout(() => {
425:         document.getElementById('scannerModal').classList.remove('show');
426:         document.getElementById('scanResult').innerText = "";
427:         
428:         // メモリ上の配列の先頭（新着順）に追加して再描画
429:         allBooks.unshift(newBook);
430:         renderBooks(allBooks);
431:         
432:         // 裏で一応CSVの再取得もリクエストしておく
433:         const sheetUrl = localStorage.getItem('sheetCsvUrl');
434:         if (sheetUrl) fetchDataFromUrl(sheetUrl);
435:     }, 3000);
436: }
