482: function fetchDataFromUrl(url) {
483:     document.getElementById('bookGrid').innerHTML = '<div class="empty-state"><p>データを読み込み中...</p></div>';
484:     
485:     if (url.includes('/edit')) {
486:         document.getElementById('bookGrid').innerHTML = '<div class="empty-state" style="color: #fca5a5;"><p>⚠️ エラー: URLが間違っています</p><p class="sub-text">ブラウザの上のURL（/edit...）ではなく、「ファイル」＞「共有」＞「ウェブに公開」で発行された <strong>/pub?output=csv</strong> で終わるURLを入力してください。</p></div>';
487:         return;
488:     }
489: 
490:     if (url.includes('/pubhtml')) {
491:         url = url.replace('/pubhtml', '/pub');
492:         if (!url.includes('output=csv')) {
493:             url += url.includes('?') ? '&output=csv' : '?output=csv';
494:         }
495:     }
496:     
497:     // キャッシュ回避のためのパラメータを追加
498:     const fetchUrl = url + (url.includes('?') ? '&' : '?') + 't=' + new Date().getTime();
499: 
500:     fetch(fetchUrl, { cache: 'no-store' })
501:         .then(response => {
502:             if (!response.ok) throw new Error(`HTTPエラー ${response.status}`);
503:             return response.text();
504:         })
505:         .then(csvText => {
506:             if (csvText.trim().startsWith('<!DOCTYPE') || csvText.trim().startsWith('<html')) {
507:                 throw new Error('CSVではなくウェブページが返されました。「ウェブページ」ではなく「CSV」形式で公開されているか確認してください。');
508:             }
509:             
510:             Papa.parse(csvText, {
511:                 header: true,
512:                 skipEmptyLines: true,
513:                 complete: function(results) {
514:                     // 全データに対して最新の自動整形（著者名・日付など）を適用
515:                     results.data.forEach(book => {
516:                         if (book.Author) book.Author = cleanAuthorName(book.Author);
517:                         if (book.Title) book.Title = book.Title.trim();
518:                         if (book.Year) book.Year = normalizeDate(book.Year);
519:                     });
520: 
521:                     // 新着順にするために配列を反転
522:                     allBooks = results.data.reverse();
523:                     renderBooks(allBooks);
524:                 },
525:                 error: function(err) {
526:                     throw new Error('CSVの解析に失敗しました: ' + err.message);
527:                 }
528:             });
529:         })
530:         .catch(err => {
531:             let errorMsg = err.message;
532:             if (errorMsg === 'Failed to fetch' || errorMsg.includes('NetworkError')) {
533:                 errorMsg = 'ネットワークエラーが発生しました。URLが正しいか、セキュリティでブロックされていないか確認してください。';
534:             }
535:             document.getElementById('bookGrid').innerHTML = `<div class="empty-state" style="color: #fca5a5;"><p>⚠️ エラーが発生しました: ${errorMsg}</p></div>`;
536:         });
537: }
