568:             if (displayStatus === '読書中') displayStatus = 'いま読んでる';
569:             
570:             let bg = 'rgba(56, 189, 248, 0.2)';
571:             let color = '#7dd3fc';
572:             if (displayStatus === '読み終わった') { bg = 'rgba(52, 211, 153, 0.2)'; color = '#6ee7b7'; }      // 緑系
573:             else if (displayStatus === 'いま読んでる') { bg = 'rgba(56, 189, 248, 0.2)'; color = '#7dd3fc'; } // 青系
574:             else if (displayStatus === '積読') { bg = 'rgba(251, 191, 36, 0.2)'; color = '#fcd34d'; }        // 黄系
