589:         const onloadScript = `if(this.naturalWidth <= 1) { this.onload=null; this.src='${openbdUrl}'; }`;
590:         const coverUrl = book.ISBN13 ? amazonUrl : 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
591:         // 背景色を透明にすることで、Amazonの1x1透明GIFが返ってきた場合でも下のテキストが見えるようにする
592:         const imgTag = book.ISBN13 ? `<img src="${amazonUrl}" alt="書影" style="width: 100%; height: 100%; object-fit: cover; box-shadow: 0 4px 6px rgba(0,0,0,0.3); position: relative; z-index: 1; background: transparent;" onload="${onloadScript}" onerror="${fallbackScript}">` : '';
593: 
594:         // 書影を表示するためのフレックスレイアウトを追加
595:         card.style.display = 'flex';
596:         card.style.gap = '15px';
597:         
598:         card.innerHTML = `
