653:     
654:     // 元の並び順（シートと同じ古い順）に戻してエクスポート
655:     const exportData = [...allBooks].reverse();
656:     const csv = Papa.unparse(exportData);
657:     // BOM付きのCSVファイルを作成（Excelでの文字化け防止）
658:     const blob = new Blob([new Uint8Array([0xEF, 0xBB, 0xBF]), csv], { type: 'text/csv;charset=utf-8;' });
659:     const url = URL.createObjectURL(blob);
