302: function cleanAuthorName(authorStr) {
303:     if (!authorStr) return "";
304:     
305:     // 1. 役割や生没年を削除
306:     authorStr = authorStr.replace(/[\/／\s\[\(]*?(著|編|訳|原作|作画|原案)[\]\)]?/g, '');
307:     authorStr = authorStr.replace(/,?\s*\d{4}-?\s*/g, ' '); // remove years
308:     
309:     // 2. スラッシュ・中黒の周りのスペースを削除
310:     authorStr = authorStr.replace(/\s*([\/／・])\s*/g, "$1");
311:     
312:     // 3. 英語同士のスペースを保護 (FGO PROJECT 等)
313:     authorStr = authorStr.replace(/([A-Za-z0-9\.\-])\s+([A-Za-z0-9\.\-])/g, "$1__SPACE__$2");
314:     
315:     // 4. First Pass Last, First Merger (NDL対策)
316:     const replacer = (match, p1, p2, p3, p4) => {
317:         let last = p2;
318:         let first = p3;
319:         let kanjiMatch = last.match(/[\u4E00-\u9FFF]/g);
320:         let kanjiCount = kanjiMatch ? kanjiMatch.length : 0;
321:         if (kanjiCount <= 2 && last.length <= 4) {
322:             return p1 + last + first;
323:         }
324:         return match;
325:     };
326:     
327:     // 先読みアサーション (?=$|[\s\/／・,]) を使用して、再帰的結合を防止
328:     let regex = /(^|[\s\/／・])([\u4E00-\u9FFF\u3040-\u309F\u30A0-\u30FFA-Za-z]{1,4})\s*,\s*([\u4E00-\u9FFF\u3040-\u309F\u30A0-\u30FFA-Za-z]{1,4}[^\s,]*)(?=$|[\s\/／・,])/g;
329:     authorStr = authorStr.replace(regex, replacer);
330:     
331:     // 5. 残ったスペースと読点をカンマに変換（複数著者の区切り）
332:     authorStr = authorStr.replace(/[\s、，]+/g, ', ');
333:     
334:     // 6. 保護した英語スペースを戻す
335:     authorStr = authorStr.replace(/__SPACE__/g, ' ');
336:     
337:     // 重複カンマを整理
338:     authorStr = authorStr.replace(/(,\s*)+/g, ', ');
339:     
340:     // 7. Second Pass Last, First Merger (スペースがカンマに変わった後に再結合)
341:     authorStr = authorStr.replace(regex, replacer);
342:     
343:     // 8. 中黒・スラッシュの処理 (カタカナ・英語なら結合、漢字なら分離)
344:     let tokens = authorStr.split(/([,・\/／])/);
345:     let authors = [];
346:     let curr = "";
347:     
348:     for (let i = 0; i < tokens.length; i++) {
349:         let token = tokens[i].trim();
350:         if (!token) continue;
351:         
352:         if (token === ',') {
353:             if (curr) { authors.push(curr); curr = ""; }
354:         } else if (token === '・' || token === '/' || token === '／') {
355:             if (/[A-Za-z\u30A0-\u30FF]/.test(curr) || (i + 1 < tokens.length && /[A-Za-z\u30A0-\u30FF]/.test(tokens[i+1]))) {
356:                 curr += token;
357:             } else {
358:                 if (curr) { authors.push(curr); curr = ""; }
359:             }
360:         } else {
361:             curr += token;
362:         }
363:     }
364:     if (curr) authors.push(curr);
365:     
366:     return authors.map(a => a.trim()).filter(a => a).join(', ');
367: }
