369: function normalizeDate(dateStr) {
370:     if (!dateStr) return "";
371:     let s = dateStr.replace(/[^\d\-]/g, '');
372:     if (/^\d{8}$/.test(s)) {
373:         return `${s.substring(0,4)}-${s.substring(4,6)}-${s.substring(6,8)}`;
374:     }
375:     if (/^\d{6}$/.test(s)) {
376:         // 月までしかない不完全なデータは「1日」にならないよう年(4桁)のみ抽出
377:         return s.substring(0,4);
378:     }
379:     if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
380:         return s;
381:     }
382:     if (/^\d{4}-\d{2}$/.test(s)) {
383:         // 月までしかない不完全なデータは「1日」にならないよう年(4桁)のみ抽出
384:         return s.substring(0,4);
385:     }
386:     if (/^\d{4}$/.test(s)) {
387:         return s;
388:     }
389:     return s;
390: }
