89: // ==========================================
90: // 2. バックグラウンド要約処理 (processMissingSummaries)
91: // ==========================================
92: // トリガー（時計マーク）から「5分に1回」などの設定で自動実行される関数です。
93: function processMissingSummaries() {
94:   const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME) || SpreadsheetApp.getActiveSpreadsheet().getSheets()[0];
95:   
96:   // シートの全データを取得
97:   const data = sheet.getDataRange().getValues();
98:   const headers = data[0];
99:   
100:   // ヘッダーから必要な列のインデックスを探す
101:   const summaryColIndex = headers.findIndex(h => h === "Gemini_Summary");
102:   const titleColIndex = headers.findIndex(h => h === "Title");
103:   const authorColIndex = headers.findIndex(h => h === "Author");
104:   const descColIndex = headers.findIndex(h => h === "description"); // 追加されたあらすじ列
105:   
106:   if (summaryColIndex === -1) {
107:     console.error("Gemini_Summary列が見つかりません。");
108:     return;
109:   }
110:   
111:   // 処理した件数をカウント
112:   let processedCount = 0;
113:   
114:   // 2行目から下に向かって順番にチェック
115:   for (let i = 1; i < data.length; i++) {
116:     const row = data[i];
117:     const summary = row[summaryColIndex];
118:     
119:     // 空欄、または「未生成」の表記があれば処理対象
120:     if (!summary || summary === "（要約未生成）" || summary.includes("作成中")) {
121:       
122:       const title = titleColIndex !== -1 ? row[titleColIndex] : "";
123:       const author = authorColIndex !== -1 ? row[authorColIndex] : "";
124:       const officialDesc = descColIndex !== -1 ? row[descColIndex] : "";
125:       
126:       // Geminiに依頼する文章
127:       const prompt = `あなたは書店やECサイトで本の魅力を一言で伝えるプロのライターです。
128: 対象書籍について、無駄を極限まで削ぎ落とした「極めて短い紹介文」を作成してください。
129: 
130: 【厳守事項】
131: 1. 長さ：長く語らないこと。「必ず1文のみ（長くても50〜60文字程度）」で完結させてください。
132: 2. 体裁：挨拶や前置きは一切禁止。いきなり内容の核心から書き始めてください。可能であれば「〜な指南書。」「〜な第X巻。」などの体言止め（名詞）で締めくくると理想的です。改行は使わず1行で出力してください。
133: 3. シリーズ物：2巻目以降の場合、1巻目の基本設定は完全に省略し、「その巻固有の展開や見どころ」のみを鋭く抜き出してください。
134: 4. 正確性：あらすじが空欄の場合は必ずWeb検索を利用し、事実のみを書いてください。想像での補完（ハルシネーション）は厳禁です。
135: 
136: 【出力イメージ】
137: ×悪い例：「本作はプロ野球を愛する女子たちを描いたコメディです。第2巻となる今回は、ビジター応援の悲哀などが描かれた一冊となっています。」
138: 〇良い例1（実用書）：「『推し』への熱い思いや感動を、語彙力を駆使して相手に的確に伝わるように言語化するための実践的な指南書。」
139: 〇良い例2（マンガ2巻）：「ビジター応援の悲哀や球団マスコットへの偏愛など、プロ野球ファン納得の『あるある』ネタが炸裂する日常コメディ第2巻。」
140: 
141: 書名: ${title}
142: 著者: ${author}
143: あらすじ: ${officialDesc}`;
144:       
145:       try {
146:         // Gemini APIを呼び出し
147:         const generatedSummary = callGeminiAPI(prompt);
148:         
149:         // スプレッドシートに書き込む（行番号は i + 1、列番号はインデックス + 1）
150:         sheet.getRange(i + 1, summaryColIndex + 1).setValue(generatedSummary);
151:         
152:       } catch (error) {
153:         console.error("行 " + (i + 1) + " の要約取得エラー: " + error.message);
154:         // クォータ（制限）やAPI側の高負荷（High Demand）の場合は、これ以上続けてもエラーになるため即座に強制終了する
155:         const errMsg = error.message.toLowerCase();
156:         if (errMsg.includes("quota") || errMsg.includes("429") || errMsg.includes("high demand") || errMsg.includes("503")) {
157:            console.log("AIサーバーが混雑しているか制限に達したため一時中断します。5分後に自動で再開されます。");
158:            return; 
159:         }
160:       } finally {
161:         // 成功でも失敗でもカウントを進める（無限ループによるタイムアウトを防ぐため）
162:         processedCount++;
163:       }
164:       
165:       // 3.5 Flashの無料枠（1分間15回まで）に合わせて8秒待機する
166:       Utilities.sleep(8000);
167:       
168:       // GASは1回の実行時間が「最大6分」というルールのための安全策
169:       // 1回の実行で最大「30件」まで処理したら終了して次回に持ち越す
170:       if (processedCount >= 30) {
171:         console.log("一度に処理できる上限に達したため、残りは次回の実行に持ち越します。");
172:         break; 
173:       }
174:     }
175:   }
176: }
