178: // ==========================================
179: // 3. Gemini API通信用関数
180: // ==========================================
181: function callGeminiAPI(prompt) {
182:   if (!GEMINI_API_KEY || GEMINI_API_KEY === "YOUR_GEMINI_API_KEY") {
183:     throw new Error("APIキーが設定されていません。");
184:   }
185:   
186:   // Proモデルが無料枠で使用不可（limit:0）だったため、最新かつ軽量・無料枠の広い 3.5 Flash を使用
187:   const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash:generateContent?key=${GEMINI_API_KEY}`;
188:   const payload = {
189:     "contents": [{
190:       "parts": [{"text": prompt}]
191:     }]
192:   };
193:   
194:   const options = {
195:     "method": "post",
196:     "contentType": "application/json",
197:     "payload": JSON.stringify(payload),
198:     "muteHttpExceptions": true
199:   };
200:   
201:   const response = UrlFetchApp.fetch(url, options);
202:   const json = JSON.parse(response.getContentText());
203:   
204:   if (json.error) {
205:     throw new Error(json.error.message);
206:   }
207:   
208:   return json.candidates[0].content.parts[0].text.trim();
209: }
